ALTER TABLE crd.outcome_update ADD CONSTRAINT ck_outcome_confidence CHECK ((confidence = 'Service-confirmed') = (source_type IN ('COLLECTION_SERVICE_CONFIRMATION','HOSPITAL_CONFIRMATION','PARTNER_INTEGRATION')));
ALTER TABLE crd.outcome_update ADD CONSTRAINT ck_outcome_phone_source CHECK (channel <> 'PHONE' OR (reported_by_name IS NOT NULL AND recorded_by IS NOT NULL));
ALTER TABLE req.blood_request ADD CONSTRAINT ck_blood_request_milestone CHECK (first_willing_at IS NULL OR first_invited_at IS NULL OR first_willing_at >= first_invited_at);
ALTER TABLE src.match_candidate ADD CONSTRAINT ck_match_candidate_reason CHECK (included OR cardinality(reason_codes) >= 1);
ALTER TABLE src.match_candidate ADD CONSTRAINT ck_match_candidate_rank CHECK (rank IS NULL OR included);
ALTER TABLE apt.appointment_slot ADD CONSTRAINT ck_slot_capacity CHECK (booked_count BETWEEN 0 AND capacity);
ALTER TABLE idn.permission_scope ADD CONSTRAINT ck_permission_scope_area CHECK (scope_code <> 'scope.area' OR area_id IS NOT NULL);
ALTER TABLE idn.staff_invitation ADD CONSTRAINT ck_staff_invitation_role CHECK (role_code IN ('SUP','MOD','ADM'));
ALTER TABLE idn.donor_location ADD CONSTRAINT ck_donor_location_approval CHECK (status <> 'Approved' OR (validated_at IS NOT NULL AND (confirmed_by_donor_at IS NOT NULL OR (approved_by IS NOT NULL AND call_reference IS NOT NULL))));
ALTER TABLE idn.donor_location ADD CONSTRAINT ck_donor_location_rejected CHECK (status <> 'Rejected' OR rejection_reason IS NOT NULL);
ALTER TABLE aud.data_export ADD CONSTRAINT ck_data_export_approver CHECK (approved_by IS NULL OR approved_by <> requested_by);
ALTER TABLE aud.data_export ADD CONSTRAINT ck_data_export_generated CHECK (status <> 'Generated' OR file_hash IS NOT NULL);
ALTER TABLE aud.data_export ADD CONSTRAINT ck_data_export_rejected CHECK (status <> 'Rejected' OR decision_reason IS NOT NULL);
ALTER TABLE src.search_event ADD CONSTRAINT ck_search_event_basic CHECK (search_type <> 'BASIC' OR context_request_id IS NOT NULL);
ALTER TABLE src.search_event ADD CONSTRAINT ck_search_event_advanced CHECK (search_type <> 'ADVANCED' OR reason_code IS NOT NULL);
ALTER TABLE aud.status_history ADD CONSTRAINT ck_status_history_distinct CHECK (from_status IS DISTINCT FROM to_status);
ALTER TABLE aud.status_history ADD CONSTRAINT ck_status_history_actor CHECK ((actor_role = 'SYSTEM') = (actor_user_id IS NULL));
ALTER TABLE aud.audit_event ADD CONSTRAINT ck_audit_event_reason CHECK (result <> 'SUCCESS' OR reason_code IS NOT NULL OR category NOT IN ('SENSITIVE_READ','EXPORT','PERMISSION','APPROVAL'));
